-- WastePilot — Reset customers from Excel source
-- Run in Supabase SQL Editor
-- This replaces all DB customers with the 264 clean records from abonnement2026.xlsx

DO $$
DECLARE
  v_org_id UUID;
  v_sec_ay UUID;
  v_sec_k1e UUID;
  v_sec_k2 UUID;
BEGIN
  -- Get the org
  SELECT id INTO v_org_id FROM organizations LIMIT 1;
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'No organization found. Run wastepilot_complete_setup.sql first.';
  END IF;

  -- Get sector IDs
  SELECT id INTO v_sec_ay  FROM sectors WHERE org_id = v_org_id AND (name ILIKE '%Alpha Yaya%' OR code = 'AY') LIMIT 1;
  SELECT id INTO v_sec_k1e FROM sectors WHERE org_id = v_org_id AND (name ILIKE '%Koloma 1%'   OR code = 'K1E') LIMIT 1;
  SELECT id INTO v_sec_k2  FROM sectors WHERE org_id = v_org_id AND (name ILIKE '%Koloma 2%'   OR code = 'K2') LIMIT 1;

  -- Delete all existing customers (cascades to subscriptions, billing_charges, payments)
  DELETE FROM customers WHERE org_id = v_org_id;

  -- Insert clean customers from Excel

  RAISE NOTICE 'Inserted % customers', (SELECT COUNT(*) FROM customers WHERE org_id = v_org_id);
END;
$$;

-- Verify
SELECT COUNT(*) AS total_customers, status FROM customers GROUP BY status;